<section class="admin-content"><div class="admin-heading"><div><div class="eyebrow">مدیریت اعضا</div><h1>کاربران سایت</h1></div><div class="filter-links"><a href="<?= url('/admin/users') ?>">همه</a><a href="<?= url('/admin/users?status=pending') ?>">در انتظار تأیید</a><a href="<?= url('/admin/users?status=active') ?>">فعال</a></div></div><?php if ($message = Session::flash('success')): ?><div class="alert success"><?= e($message) ?></div><?php endif; ?><?php if ($message = Session::flash('error')): ?><div class="alert error"><?= e($message) ?></div><?php endif; ?><div class="admin-panel table-wrap"><table><thead><tr><th>کاربر</th><th>نقش</th><th>کشور</th><th>وضعیت</th><th>عضویت</th><th>عملیات</th></tr></thead><tbody><?php foreach ($users as $user): ?><tr><td><strong><?= e($user['display_name'] ?: $user['email']) ?></strong><small><?= e($user['email']) ?></small></td><td><?= $user['role'] === 'freelancer' ? 'فریلنسر' : ($user['role'] === 'employer' ? 'کارفرما' : 'مدیر') ?></td><td><?= e($user['country'] ?: '—') ?></td><td><span class="status status-<?= e($user['status']) ?>"><?= $user['status'] === 'pending' ? 'در انتظار' : ($user['status'] === 'active' ? 'فعال' : 'تعلیق‌شده') ?></span></td><td><?= e($user['created_at']) ?></td><td><?php if ($user['role'] !== 'admin' && $user['status'] !== 'active'): ?><form class="inline-form" method="post" action="<?= url('/admin/users/verify') ?>"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= e($user['id']) ?>"><button class="action-button approve" type="submit">تأیید</button></form><?php endif; ?><?php if ($user['role'] !== 'admin' && $user['status'] !== 'suspended'): ?><form class="inline-form" method="post" action="<?= url('/admin/users/suspend') ?>"><?= csrf_field() ?><input type="hidden" name="user_id" value="<?= e($user['id']) ?>"><button class="action-button suspend" type="submit">تعلیق</button></form><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$users): ?><tr><td colspan="6" class="empty">کاربری با این فیلتر پیدا نشد.</td></tr><?php endif; ?></tbody></table></div></section>
